import{_ as t,o as u,c as e,ag as q}from"./chunks/framework.B5ULsuav.js";const p=JSON.parse('{"title":"道家金句","description":"","frontmatter":{},"headers":[],"relativePath":"40-原话金句/quote-道家.md","filePath":"40-原话金句/quote-道家.md","lastUpdated":1778155802000}'),a={name:"40-原话金句/quote-道家.md"};function r(l,o,s,n,c,k){return u(),e("div",null,[...o[0]||(o[0]=[q('<h1 id="道家金句" tabindex="-1">道家金句 <a class="header-anchor" href="#道家金句" aria-label="Permalink to &quot;道家金句&quot;">​</a></h1><blockquote><p>了空居士讲解《道德经》精彩原话集 含：道与自然、守中、无为、柔弱、修行处世</p></blockquote><hr><h2 id="一、道与自然" tabindex="-1">一、道与自然 <a class="header-anchor" href="#一、道与自然" aria-label="Permalink to &quot;一、道与自然&quot;">​</a></h2><blockquote><p><strong>&quot;无为不是什么都不做，是无妄为——不违背客观规律去乱搞。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/金刚经11分-无为即无妄为">金刚经11分-无为即无妄为</a></p></blockquote><blockquote><p><strong>&quot;无为就是按照客观实际情况去做。该怎么做就怎么做，不添加个人主观的妄念。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/金刚经11分-无为即无妄为">金刚经11分-无为即无妄为</a></p></blockquote><blockquote><p><strong>&quot;道无处不在。大到宇宙星辰，小到一草一木，都在道中。你不需要去远方找道，就在你眼前。&quot;</strong> ——道德经讲解</p></blockquote><blockquote><p><strong>&quot;观天之道，执天之行——观察大自然的规律，并以此规范我们的行为。这就是修行的开始。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/中论丹道-观天之道执天之行">中论丹道-观天之道执天之行</a></p></blockquote><blockquote><p><strong>&quot;人法地，地法天，天法道，道法自然——人效法地，地效法天，天效法道，道效法它自己的样子。一切都是自然而然。&quot;</strong> ——道德经讲解</p></blockquote><hr><h2 id="二、守中" tabindex="-1">二、守中 <a class="header-anchor" href="#二、守中" aria-label="Permalink to &quot;二、守中&quot;">​</a></h2><blockquote><p><strong>&quot;多言数穷，不如守中——话说多了反而说不清楚，不如保持内心清净，该说就说，不该说就不说。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/道德经5章-多言数穷不如守中">道德经5章-多言数穷不如守中</a></p></blockquote><blockquote><p><strong>&quot;守中不是停在中间不动，是不走极端。就像开车，要不断微调方向才能保持在车道中间。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/道德经5章-多言数穷不如守中">道德经5章-多言数穷不如守中</a></p></blockquote><blockquote><p><strong>&quot;知其雄，守其雌——知道自己的力量，但要保持谦卑。不是软弱，是真正的强者之态。&quot;</strong> ——道德经讲解</p></blockquote><blockquote><p><strong>&quot;大智若愚——真正有智慧的人看起来好像很愚笨，因为他不显摆。&quot;</strong> ——道德经讲解</p></blockquote><hr><h2 id="三、无为与自然务实" tabindex="-1">三、无为与自然务实 <a class="header-anchor" href="#三、无为与自然务实" aria-label="Permalink to &quot;三、无为与自然务实&quot;">​</a></h2><blockquote><p><strong>&quot;为学日益，为道日损——学知识是每天增加的，修道是每天减少的。减少的是什么？减少的是执着和妄念。&quot;</strong> ——道德经讲解</p></blockquote><blockquote><p><strong>&quot;上善若水——最高的善像水一样。水善利万物而不争，处众人之所恶，故几于道。&quot;</strong> ——道德经讲解</p></blockquote><blockquote><p><strong>&quot;天下难事必作于易，天下大事必作于细——难的事情要从容易处下手，大的事情要从细微处开始。&quot;</strong> ——道德经讲解</p></blockquote><blockquote><p><strong>&quot;合抱之木，生于毫末——再大的树也是从小芽长起来的。修行也是一样，不要看不起一点点功夫。&quot;</strong> ——道德经讲解</p></blockquote><blockquote><p><strong>&quot;千里之行，始于足下——最终的目的地不重要啊，走起来最重要了！&quot;</strong> ——道德经讲解</p></blockquote><hr><h2 id="四、柔弱与不争" tabindex="-1">四、柔弱与不争 <a class="header-anchor" href="#四、柔弱与不争" aria-label="Permalink to &quot;四、柔弱与不争&quot;">​</a></h2><blockquote><p><strong>&quot;天下之至柔，驰骋天下之至坚——水是最柔的，但滴水可以穿石。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/道德经43章-柔弱胜刚强">道德经43章-柔弱胜刚强</a></p></blockquote><blockquote><p><strong>&quot;夫唯不争，故天下莫能与之争——你不争，别人就没办法跟你争。因为争需要一个对手，而你没有站在对手的位置。&quot;</strong> ——道德经讲解</p></blockquote><blockquote><p><strong>&quot;挫其锐，解其纷，和其光，同其尘——收敛锋芒，在光明之处能待，在凡俗之处也能待。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/道德经4章-和光同尘">道德经4章-和光同尘</a></p></blockquote><hr><h2 id="五、有与无" tabindex="-1">五、有与无 <a class="header-anchor" href="#五、有与无" aria-label="Permalink to &quot;五、有与无&quot;">​</a></h2><blockquote><p><strong>&quot;有之以为利，无之以为用——比如一个杯子，中间空的地方才能装水。修行要&#39;放空&#39;，放空了才有用。&quot;</strong> ——道德经讲解</p></blockquote><blockquote><p><strong>&quot;少则得，多则惑——想要得太多，反而什么都得不到。专注一件事，反而能做成。&quot;</strong> ——道德经讲解</p></blockquote><blockquote><p><strong>&quot;知足不辱，知止不殆——知道满足就不会受辱，知道适可而止就不会有危险。&quot;</strong> ——道德经讲解</p></blockquote><hr><h2 id="六、修行与处世" tabindex="-1">六、修行与处世 <a class="header-anchor" href="#六、修行与处世" aria-label="Permalink to &quot;六、修行与处世&quot;">​</a></h2><blockquote><p><strong>&quot;五色令人目盲，五音令人耳聋——外在的东西太多，反而迷了本心。不是不要色彩音乐，是不要被它们牵着走。&quot;</strong> ——道德经讲解</p></blockquote><blockquote><p><strong>&quot;致虚极，守静笃——把心放空到极致，守住极致的宁静。静到极处，万物的真相就现前了。&quot;</strong> ——道德经讲解</p></blockquote><blockquote><p><strong>&quot;天之道，损有余而补不足——自然的规律是减少多余的去补充不足的。做人也要这样，不要只顾自己。&quot;</strong> ——道德经讲解</p></blockquote><blockquote><p><strong>&quot;圣人无常心，以百姓心为心——真正有智慧的人没有自己的私心，以大家的利益为利益。&quot;</strong> ——道德经讲解</p></blockquote><blockquote><p><strong>&quot;火候无差其实就跟瓜熟蒂落、水到渠成是一致的，这个火候是不用传的，是自然的。道法自然嘛。&quot;</strong> ——答疑专辑2019_修炼篇</p></blockquote><hr><h2 id="简短金句" tabindex="-1">简短金句 <a class="header-anchor" href="#简短金句" aria-label="Permalink to &quot;简短金句&quot;">​</a></h2><blockquote><p>&quot;顺其自然。&quot; &quot;知止。&quot; &quot;静观其变。&quot; &quot;有功不居。&quot; &quot;以柔克刚。&quot; &quot;道法自然。&quot;</p></blockquote><hr><blockquote><p>来源：<a href="/liaokongjushi-wisdom/01-Raw-Sources/道德经讲解">道德经讲解</a> 整理日期：2026-05-06 | 重构：2026-05-07（新增火候自然、柔弱胜刚强原文出处、有无论述）</p></blockquote>',44)])])}const i=t(a,[["render",r]]);export{p as __pageData,i as default};
